def admit(active, waiting, budget, slots):
    # Check if any waiting reservation exceeds the total budget
    for value in waiting:
        if value > budget:
            raise ValueError("Waiting reservation exceeds budget")

    admitted = []
    for value in waiting:
        # Stop if adding this value exceeds budget
        if sum(active) + sum(admitted) + value > budget:
            break
        # Stop if adding this value exceeds the slots limit
        if len(active) + len(admitted) >= slots:
            break
        # Admit this value (FIFO order)
        admitted.append(value)

    remaining = [v for v in waiting if v not in admitted]
    return admitted, remaining

