def admit(active, waiting, budget, slots):
    # Check if any waiting reservation exceeds total budget
    for value in waiting:
        if value > budget:
            raise ValueError("oversized tail reservation")

    admitted = []
    active_sum = sum(active)
    active_count = len(active)

    for value in waiting:
        # Check if admitting this value violates budget
        if active_sum + sum(admitted) + value > budget:
            break
        # Check if admitting this value violates slots limit
        if active_count + len(admitted) + 1 > slots:
            break
        # Admit this value (FIFO: just add it)
        admitted.append(value)

    # Build remaining list, handling duplicates properly
    remaining = []
    temp_admitted = admitted.copy()
    for value in waiting:
        if value in temp_admitted:
            temp_admitted.remove(value)  # removes one occurrence
        else:
            remaining.append(value)

    return admitted, remaining
